import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import type { JsonLdDocument } from "jsonld";

import { computeContentHash } from "./content-hash.js";
import { newDocumentLoader } from "./documentLoader.js";

// Goldens are generated by the Go declaration bindings; matching them here pins TS to Go.
const declarationsDir = resolve(dirname(fileURLToPath(import.meta.url)), "../../../..");

interface GoldenFile {
  context_url: string;
  cases: { name: string; declaration: Record<string, unknown>; content_hash: string }[];
}

function readJSON<T>(rel: string): T {
  return JSON.parse(readFileSync(resolve(declarationsDir, rel), "utf-8")) as T;
}

for (const decl of ["SettlementResult", "BidDecline"]) {
  describe(`${decl} content-hash golden`, () => {
    const golden = readJSON<GoldenFile>(`${decl}/v1/conformance/content-hash-golden.json`);
    const loader = newDocumentLoader({
      [golden.context_url]: readJSON<JsonLdDocument>(`${decl}/v1/context.jsonld`),
    });

    it("has cases", () => {
      expect(golden.cases.length).toBeGreaterThan(0);
    });

    for (const c of golden.cases) {
      it(`reproduces ${c.name}`, async () => {
        expect(await computeContentHash(c.declaration, golden.context_url, loader)).toBe(
          c.content_hash
        );
      });
    }
  });
}

// Same inputs and values as the Go TestComputeResponseHash_Golden, so the AuthorizationResponse
// response_hash is pinned in both languages.
describe("AuthorizationResponse response_hash golden", () => {
  const contextUrl =
    "https://schemas.atum.network/declarations/AuthorizationResponse/v1/context.jsonld";
  const loader = newDocumentLoader({
    [contextUrl]: readJSON<JsonLdDocument>("AuthorizationResponse/v1/context.jsonld"),
  });
  const ctx = [contextUrl, "https://w3id.org/security/suites/secp256k1recovery-2020/v2"];
  const cases: [string, Record<string, unknown>, string][] = [
    [
      "authorized-with-proof",
      {
        "@context": ctx,
        payment_id: "0x1234abcd",
        counterparty_did: "did:pkh:eip155:1:0x70997970c51812dc3a010c7d01b50e0d17dc79c8",
        status: "authorized",
        proof: {
          type: "EcdsaSecp256k1RecoverySignature2020",
          created: "2026-05-20T00:01:00Z",
          verificationMethod:
            "did:pkh:eip155:1:0x70997970c51812dc3a010c7d01b50e0d17dc79c8#blockchainAccountId",
          proofPurpose: "assertionMethod",
          jws: "eyJhbGciOiJFUzI1NkstUiIsImI2NCI6ZmFsc2UsImNyaXQiOlsiYjY0Il19..SIG",
        },
      },
      "0x83d5bbdc1185f4341a99c9f9466425964d2f70baa0b0d2519cf70d8b2fa66607",
    ],
    [
      "declined-non-ascii-reason",
      {
        "@context": ctx,
        payment_id: "0x1234abcd",
        counterparty_did: "did:pkh:eip155:1:0x70997970c51812dc3a010c7d01b50e0d17dc79c8",
        status: "declined",
        reason: 'compte suspendu: vérification échouée "KYC"\n口座',
      },
      "0x3a608667738d89929b14defb8f71b1e1049c123dc08163ad14e8fff787ccb8bb",
    ],
  ];
  for (const [name, doc, want] of cases) {
    it(`reproduces ${name}`, async () => {
      expect(await computeContentHash(doc, contextUrl, loader)).toBe(want);
    });
  }
});

describe("computeContentHash", () => {
  const golden = readJSON<GoldenFile>("BidDecline/v1/conformance/content-hash-golden.json");
  const loader = newDocumentLoader({
    [golden.context_url]: readJSON<JsonLdDocument>("BidDecline/v1/context.jsonld"),
  });
  const { declaration, content_hash } = golden.cases[0];

  it("ignores the wire @context, proof and verifiableCredential", async () => {
    const noisy = {
      ...declaration,
      "@context": ["https://www.w3.org/2018/credentials/v1", golden.context_url],
      proof: { type: "EcdsaSecp256k1RecoverySignature2020" },
      verifiableCredential: [{ id: "urn:uuid:ignored" }],
    };
    expect(await computeContentHash(noisy, golden.context_url, loader)).toBe(content_hash);
  });

  it("rejects an empty context URL", async () => {
    await expect(computeContentHash(declaration, "", loader)).rejects.toThrow(TypeError);
  });

  it("fails closed on a context the loader cannot resolve", async () => {
    await expect(
      computeContentHash(declaration, "https://example.com/unknown/context.jsonld", loader)
    ).rejects.toThrow();
  });
});
